private int rritshuma = 0;

private void ReportHeader_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
xrPictureBox1.Image = AlphaWebReports.raporteUtil.MerrLogoNdermarrje(this.Extensions["ndermarrjeLogo"]);

}


private void xrTableCell_SummaryGetResult(object sender, SummaryGetResultEventArgs e)
{
	XRLabel p = (XRLabel) sender;
	XtraReport report = (XtraReport)p.Report;
	int shifraPasPresjes = (int)report.Parameters["parameterFormatNumri"].Value;

            double shuma = 0;
            for (int i = 0; i < e.CalculatedValues.Count; i++)
                if (e.CalculatedValues[i].ToString().Contains("("))
                    shuma -= double.Parse(e.CalculatedValues[i].ToString().Replace('(', ' ').Replace(')', ' '));
                else shuma += double.Parse(e.CalculatedValues[i].ToString());
                   if (shuma >= 0)
   				{
                          double result = shuma/1000;
                           e.Result =  result.ToString("N" + shifraPasPresjes);
				}
                          else 
				{ double result = -shuma/1000;
 				  e.Result = "(" + result.ToString("N" + shifraPasPresjes) + ")";
				} 
            e.Handled = true;

        }

private void xrTableCell_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e)
  {
	XRLabel p = (XRLabel) sender;
	XtraReport report = (XtraReport)p.Report;
	int shifraPasPresjes = (int)report.Parameters["parameterFormatNumri"].Value;

                  double shuma = 0;
            XRTableCell label = sender as XRTableCell;
            if (label.Text.Contains("("))
                shuma = -double.Parse(label.Text.ToString().Replace('(', ' ').Replace(')', ' '));
            else shuma = double.Parse(label.Text.ToString());
        if (shuma >= 0)
                 { 
 			double resultShuma = shuma/1000;
 			label.Text = resultShuma.ToString("N" + shifraPasPresjes);
		     }
           else 
		{ 
	         double resultShuma = -shuma;
               label.Text = "(" + resultShuma.ToString("N" + shifraPasPresjes) + ")"; 
		}
    }

private void xrTableCell55_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
  e.Result = xrTableCell55.Text;
            e.Handled = true;
}

private void xrTableCell60_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
 e.Result = xrTableCell60.Text;
            e.Handled = true;
}

private void xrTableCell55_AfterPrint(object sender, System.EventArgs e) {
  int nr = 0;
            if (xrTableCell55.Text != "")
            {
                int.TryParse(xrTableCell55.Text, out nr);

            }
		   xrTableCell55.Text = (nr+ 1 + rritshuma).ToString();

}

private void xrTableCell60_AfterPrint(object sender, System.EventArgs e) {
 int nr = 0;
            if (xrTableCell60.Text != "")
            {

                int.TryParse(xrTableCell60.Text, out nr);

            }
                xrTableCell60.Text = (nr+ 2 + rritshuma).ToString();
}
